/**
 * TASK: Build a tiny command line out of raw key events.
 *
 * Register TWO handlers on this panel -- keyTyped for characters and
 * keyPressed for the Up arrow -- following this contract exactly:
 *
 *  1. keyTyped with an ordinary printable character appends it to the
 *     buffer, but the buffer never grows past 20 characters; extra
 *     characters are dropped silently.
 *  2. keyTyped with backspace (the char '\b') removes the last character.
 *     On an empty buffer it does nothing -- it must never throw.
 *  3. keyTyped with enter (the char '\n') submits: if the buffer contains
 *     something other than spaces, its TRIMMED text is appended to the
 *     history; either way the buffer is cleared afterwards.
 *  4. The history keeps only the 3 most recent commands; when a fourth
 *     arrives the oldest is dropped.
 *  5. keyPressed with KeyEvent.VK_UP replaces the buffer with the most
 *     recent history entry. With an empty history it does nothing.
 *
 * Ignore every other control character (use Character.isISOControl to spot
 * them) and every other key code.
 *
 * Example: type "ls", press enter, press Up -> historyText() is "ls" and
 * the buffer is "ls" again.
 *
 * No window is ever opened -- the tests build KeyEvents by hand and hand
 * them straight to the registered listener.
 */
import java.util.ArrayList;
import java.util.List;
import javax.swing.JPanel;

public class CommandLineBuffer extends JPanel {

    private static final int MAX_LENGTH = 20;
    private static final int MAX_HISTORY = 3;

    private String buffer = "";
    private final List<String> history = new ArrayList<>();

    public CommandLineBuffer() {
        // TODO: addKeyListener(...) handling keyTyped (characters, backspace,
        // TODO: enter) and keyPressed (the Up arrow)
    }

    public String buffer() {
        // TODO: the text typed so far
        return "";
    }

    public List<String> history() {
        return new ArrayList<>(history);
    }

    public String historyText() {
        return String.join("|", history);
    }
}

