import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;

public class CommandLineBufferTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void type(CommandLineBuffer panel, char ch) {
        KeyEvent event = new KeyEvent(panel, KeyEvent.KEY_TYPED,
                System.currentTimeMillis(), 0, KeyEvent.VK_UNDEFINED, ch);
        for (KeyListener listener : panel.getKeyListeners()) {
            listener.keyTyped(event);
        }
    }

    static void type(CommandLineBuffer panel, String text) {
        for (int i = 0; i < text.length(); i++) {
            type(panel, text.charAt(i));
        }
    }

    static void press(CommandLineBuffer panel, int keyCode) {
        KeyEvent event = new KeyEvent(panel, KeyEvent.KEY_PRESSED,
                System.currentTimeMillis(), 0, keyCode, KeyEvent.CHAR_UNDEFINED);
        for (KeyListener listener : panel.getKeyListeners()) {
            listener.keyPressed(event);
        }
    }

    public static void main(String[] args) {
        try {
            CommandLineBuffer panel = new CommandLineBuffer();
            check("a KeyListener is registered", true, panel.getKeyListeners().length >= 1);
            check("buffer starts empty", "", panel.buffer());

            type(panel, '\b');
            check("backspace on an empty buffer is harmless", "", panel.buffer());

            type(panel, "ls -l");
            check("typed characters collect", "ls -l", panel.buffer());

            type(panel, '\b');
            type(panel, '\b');
            check("backspace removes the last character", "ls ", panel.buffer());

            type(panel, '\n');
            check("enter clears the buffer", "", panel.buffer());
            check("enter stores the trimmed command", "ls", panel.historyText());

            type(panel, "   ");
            type(panel, '\n');
            check("a blank command is not stored", "ls", panel.historyText());
            check("but the buffer is still cleared", "", panel.buffer());

            for (String command : new String[] { "one", "two", "three" }) {
                type(panel, command);
                type(panel, '\n');
            }
            check("history keeps only the last three", "one|two|three", panel.historyText());

            press(panel, KeyEvent.VK_UP);
            check("the Up arrow recalls the newest command", "three", panel.buffer());

            type(panel, '\n');
            type(panel, "0123456789012345678901234");
            check("the buffer stops at twenty characters", 20, panel.buffer().length());
            check("and keeps the first twenty", "01234567890123456789", panel.buffer());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

