import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JPanel;

public class CommandLineBuffer extends JPanel {

    private static final int MAX_LENGTH = 20;
    private static final int MAX_HISTORY = 3;

    private String buffer = "";
    private final List<String> history = new ArrayList<>();

    public CommandLineBuffer() {
        addKeyListener(new KeyAdapter() {
            @Override
            public void keyTyped(KeyEvent e) {
                char typed = e.getKeyChar();
                if (typed == '\b') {
                    if (!buffer.isEmpty()) {
                        buffer = buffer.substring(0, buffer.length() - 1);
                    }
                } else if (typed == '\n') {
                    submit();
                } else if (!Character.isISOControl(typed)) {
                    if (buffer.length() < MAX_LENGTH) {
                        buffer = buffer + typed;
                    }
                }
            }

            @Override
            public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_UP && !history.isEmpty()) {
                    buffer = history.get(history.size() - 1);
                }
            }
        });
    }

    private void submit() {
        String command = buffer.trim();
        if (!command.isEmpty()) {
            history.add(command);
            if (history.size() > MAX_HISTORY) {
                history.remove(0);
            }
        }
        buffer = "";
    }

    public String buffer() {
        return buffer;
    }

    public List<String> history() {
        return new ArrayList<>(history);
    }

    public String historyText() {
        return String.join("|", history);
    }
}
